body, html {
  margin: 0;
  padding: 0;
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: #ffffff;
}

#chat-container {
  height: 100%;
  overflow-y: auto;
  padding: 15px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.message-box {
  max-width: 80%;
  padding: 12px 16px;
  border-radius: 8px;
  line-height: 1.5;
  font-size: 14px;
}

.message-box.user {
  align-self: flex-end;
  background-color: #f7fafc;
  border: 1px solid #e2e8f0;
  color: #2d3748;
}

.message-box.model {
  align-self: flex-start;
  background-color: #ebf8ff;
  border-left: 4px solid #3182ce;
  color: #2b6cb0;
}

.sender-title {
  font-weight: bold;
  font-size: 11px;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.empty-state {
  text-align: center;
  color: #a0aec0;
  margin-top: 40px;
  font-style: italic;
}

