// Globale Funktion zum sicheren Rendern
function renderChatFromModel(model) {
  let messages = [];
  try {
    const rawData = model && model.chatData ? model.chatData : window.appsmith && window.appsmith.model && window.appsmith.model.chatData;
    if (typeof rawData === 'string') {
      messages = JSON.parse(rawData);
    } else if (Array.isArray(rawData)) {
      messages = rawData;
    } else if (model && Array.isArray(model.messages)) {
      messages = model.messages;
    }
  } catch (e) {
    console.error("Fehler beim Parsen:", e);
  }
  const container = document.getElementById('chat-container');
  if (!container) {
    return false;
  }
  if (!messages || messages.length === 0) {
    container.innerHTML = '<div class="empty-state">Noch keine Nachrichten...</div>';
    return true;
  }
  container.innerHTML = messages.map(msg => {
    const textContent = msg.parts?.[0]?.text || msg.text || '';
    const isUser = msg.role === 'user';
    const sender = isUser ? 'Du' : 'Gemini';
    const cssClass = isUser ? 'user' : 'model';
    const renderedContent = isUser ? escapeHtml(textContent) : typeof marked !== 'undefined' ? marked.parse(textContent) : escapeHtml(textContent);
    return `
      <div class="message-box ${cssClass}">
        <div class="sender-title">${sender}</div>
        <div class="message-text">${renderedContent}</div>
      </div>
    `;
  }).join('');

  // Auto-Scroll ans Ende
  container.scrollTop = container.scrollHeight;
  return true;
}
function escapeHtml(text) {
  return (text || '').replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, '<br>');
}

// Appsmith Event
window.appsmith.onModelChange = model => {
  const success = renderChatFromModel(model);
  if (!success) {
    setTimeout(() => renderChatFromModel(model), 150);
  }
};

// Hintergrund-Check, damit asynchrone Antworten von Gemini sofort greifen
setInterval(() => {
  if (window.appsmith && window.appsmith.model) {
    renderChatFromModel(window.appsmith.model);
  }
}, 400);

// Initialer Render beim Laden
window.addEventListener('DOMContentLoaded', () => {
  if (window.appsmith && window.appsmith.model) {
    renderChatFromModel(window.appsmith.model);
  }
});

